CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `user_buy_code_tbl` AS select `u`.`userID` AS `userID`,`u`.`name` AS `name`,`c`.`code_name` AS `주소`,`b`.`prodName` AS `prodName`,`cm2`.`code_name` AS `물품분류`,`b`.`price` AS `price`,`b`.`amount` AS `amount`,(`b`.`price` * `b`.`amount`) AS `총구매액`,`cm`.`code_name` AS `통신사` from ((((`usertbl` `u` left join `buytbl` `b` on((`u`.`userID` = `b`.`userID`))) left join `code_master` `c` on(((`c`.`code_type` = 'addr') and (`c`.`code_value` = `u`.`addr`)))) left join `code_master` `cm` on(((`cm`.`code_type` = 'MOB1') and (`cm`.`code_value` = `u`.`mobile1`)))) left join `code_master` `cm2` on(((`cm2`.`code_type` = 'GRPN') and (`cm2`.`code_value` = `b`.`groupName`)))) where ((`c`.`use_yn` = 'Y') or (`cm`.`use_yn` = 'y') or (`cm2`.`use_yn` = 'Y')) order by `u`.`name`